INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (1, 2, "訓練はまだ\nここからですわ", 2, 2, 1000, 3000, "調子が上がって\nきたなっ", "vo_minigame_1013_icon_1_002_001", "vo_minigame_1013_icon_2_002_001");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (2, 2, "クスクス、悪くない\n流れですわね", 2, 2, 5000, 3000, "ほらほら、\nまだいけるだろ？", "vo_minigame_1013_icon_1_003_001", "vo_minigame_1013_icon_2_003_001");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (3, 2, "すばらしい\n記録ですわ", 2, 3, 10000, 3000, "へへっ、おまえら\nやるじゃねえか！", "vo_minigame_1013_icon_1_004_001", "vo_minigame_1013_icon_2_004_001");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (4, 2, "乗りに乗って\nいますわね", 3, 3, 10000, 3000, "あたしたちはまだ\n止まらねえぜ！", "vo_minigame_1013_icon_1_005_001", "vo_minigame_1013_icon_2_005_001");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (5, 2, "まだまだ行きます\nついてきなさい", 3, 3, 10000, 3000, "見てろよ！\nマコト班の快進撃だ！", "vo_minigame_1013_icon_1_005_002", "vo_minigame_1013_icon_2_005_002");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (6, 2, "エリコ班の\n本領発揮ですわ！", 3, 3, 10000, 3000, "うおぉぉっ！\n絶好調だぜ！", "vo_minigame_1013_icon_1_005_003", "vo_minigame_1013_icon_2_005_003");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (7, 2, "ここからは\n前人未到の領域です！", 4, 3, 0, 3000, "どこまで行けるか\n楽しみだなっ！", "vo_minigame_1013_icon_1_006_001", "vo_minigame_1013_icon_2_006_001");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (8, 3, "厄介でしたわ…", 5, 4, 1, 1000, "まだ諦めんなよっ", "vo_minigame_1013_icon_1_007_001", "vo_minigame_1013_icon_2_007_001");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (9, 3, "油断大敵です", 5, 4, 1, 1000, "冷やっとしたぜ…！", "vo_minigame_1013_icon_1_007_002", "vo_minigame_1013_icon_2_007_002");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (10, 3, "忌々しいっ…", 5, 4, 1, 1000, "弱音を吐くなっ", "vo_minigame_1013_icon_1_007_003", "vo_minigame_1013_icon_2_007_003");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (11, 4, "大所帯ですわね", 6, 3, 99, 1500, "マコト班集合！", "vo_minigame_1013_icon_1_008_001", "vo_minigame_1013_icon_2_008_001");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (12, 4, "エリコ班へようこそ", 6, 3, 99, 1500, "連携してくぞ！", "vo_minigame_1013_icon_1_008_002", "vo_minigame_1013_icon_2_008_002");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (13, 1, "ナナカちゃんに\nお任せあれ", 8, 6, 0, 3000, "みんなに力を！", "vo_minigame_1013_icon_1_020_001", "vo_minigame_1013_icon_2_020_001");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (14, 1, "はっはっは！\n任せろ！", 9, 7, 0, 3000, "任せてくれたまえ", "vo_minigame_1013_icon_1_022_001", "vo_minigame_1013_icon_2_022_001");
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (15, 1, "どんどんいくわよ", 10, 8, 0, 3000, "ほな、いきまひょか", "vo_minigame_1013_icon_1_023_001", "vo_minigame_1013_icon_2_023_001");
